      display: grid;
      place-items: center;
    }
    .magnifier {
      display: inline-block;
      width: 1em;
      height: 1em;
      position: relative;
      flex: none;
    }
    .magnifier::before {
      content: "";
      position: absolute;
      inset: 0 .22em .22em 0;
      border: max(1.4px, .085em) solid currentColor;
      border-radius: 50%;
    }
    .magnifier::after {
      content: "";
      position: absolute;
      width: .37em;
      height: max(1.4px, .085em);
      border-radius: 2px;
      background: currentColor;
      right: .025em;
      bottom: .14em;
      transform: rotate(45deg);
    }
    main { padding-block: 40px 52px; }
    h1, .summary h2 {
      font-family: Georgia, "Times New Roman", serif;
      font-weight: 400;
      letter-spacing: -.055em;
    }
    h1 { font-size: clamp(2.6rem, 5vw, 4.3rem); line-height: 1.01; }
    .intro p { margin-top: 12px; color: var(--muted); }
    .intro .preview-context { margin-top: 9px; font-size: .82rem; }
    fieldset { border: 0; padding: 0; margin: 0; min-inline-size: 0; }
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }
    .cards {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
      margin-top: 27px;
    }
    .card {
      min-width: 0;
      background: var(--white);
      border: 1px solid var(--line);
      border-radius: 17px;
      box-shadow: 0 3px 8px #30223806;
    }
    .card:has(.pick input:checked) {
      border-color: var(--accent);
      box-shadow: 0 0 0 1px var(--accent);
    }
    .card header {
      min-height: 63px;
      padding: 11px 16px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
    }
    .option-title { display: flex; align-items: center; gap: 9px; }
    .letter {
      display: grid;
      place-items: center;
      width: 27px;
      height: 27px;
      border-radius: 8px;
      background: var(--accent-wash);
      color: var(--accent);
      font-size: .79rem;
      font-weight: 750;
    }
    .card h2 { font-size: .99rem; line-height: 1.25; }
    .pick {
      display: inline-flex;
      gap: 6px;
      align-items: center;
      padding: 7px 9px;
      border: 1px solid var(--line);
      border-radius: 9px;
      font-size: .79rem;
      font-weight: 650;
      cursor: pointer;
    }
    .pick:has(input:checked) { color: var(--accent); background: var(--accent-wash); border-color: #d6b9cd; }
    .pick input { margin: 0; accent-color: var(--accent); width: 14px; height: 14px; }
    .pick .selected, .pick:has(input:checked) .choose { display: none; }
    .pick:has(input:checked) .selected { display: inline; }
    .preview {
      margin-inline: 12px;
      border: 1px solid var(--preview-line);
      border-radius: 11px;
      background: #fdfcfe;
      overflow: hidden;
      font-family: system-ui, sans-serif;
    }
    .search-bar {
      display: flex;
      align-items: center;
      gap: 8px;
      margin: 10px 10px 0;
      padding: 7px 9px;
      border: 1px solid #e5e1e8;
      border-radius: 7px;
      background: var(--white);
      color: #393440;
      font-size: .8rem;
    }
    .search-bar .magnifier { color: #6a6172; }
    .results-bar {
      padding: 8px 12px;
      border-bottom: 1px solid var(--preview-line);
      color: #655d6c;
      font-size: .73rem;
    }
    .empty {
      min-height: 189px;
      display: flex;
      flex-direction: column;
      align-items: center;
      padding: 21px 12px 23px;
      text-align: center;
    }
    .empty-icon {
      display: grid;
      place-items: center;
      width: 46px;
      height: 46px;
      border-radius: 14px;
      font-size: 23px;
      color: var(--accent);
      background: var(--accent-wash);
    }
    .empty h3 { margin-top: 12px; font-size: 1.06rem; letter-spacing: -.027em; line-height: 1.28; }
    .empty p { max-width: 30ch; margin-top: 6px; font-size: .86rem; line-height: 1.45; color: #655d6c; }
    .rating { margin: 14px 16px 16px; }
    .rating legend { padding: 0; font-size: .83rem; font-weight: 700; }
    .scale { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 5px; margin-top: 7px; }
    .score { position: relative; cursor: pointer; }
    .score span {
      display: grid;
      place-items: center;
      min-height: 34px;
      border: 1px solid var(--line);
      border-radius: 7px;
      font-size: .82rem;
      font-weight: 650;
    }
    .score:hover span, .pick:hover { background: var(--accent-wash); }
    .score input:checked + span { background: var(--accent); border-color: var(--accent); color: white; }
    .score input:focus-visible + span, .pick:has(input:focus-visible), textarea:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 3px;
    }
    .scale-labels { display: flex; justify-content: space-between; gap: 8px; margin-top: 5px; color: var(--muted); font-size: .73rem; }
    .notes { margin-top: 22px; }
    .notes label { display: block; margin-bottom: 6px; font-weight: 700; }
    .optional { margin-left: 5px; color: var(--muted); font-size: .82rem; font-weight: 400; }
    textarea {
      display: block;
      width: 100%;
      min-height: 75px;
      resize: vertical;
      padding: 11px 13px;
      border: 1px solid #cfc4cf;
      border-radius: 10px;
      background: white;
      color: inherit;
      font: inherit;
    }
    textarea::placeholder { color: var(--muted); }
    .summary {
      margin-top: 22px;
      padding: 20px 23px;
      border-radius: 16px;
      background: #34263a;
      color: #fff;
    }
    .summary h2 { font-size: 1.85rem; line-height: 1.15; }
    .summary dl {
      display: grid;
      grid-template-columns: 1fr 1.65fr 1.35fr;
      gap: 18px;
      margin-top: 14px;
      padding-top: 13px;
      border-top: 1px solid #ffffff35;
    }
    .summary dt { margin-bottom: 3px; color: #e1cddd; font-size: .78rem; font-weight: 700; }
    .summary dd { font-size: .87rem; overflow-wrap: anywhere; }
    .summary dd ul { display: flex; flex-wrap: wrap; gap: 2px 14px; list-style: none; padding: 0; margin: 0; }
