        <label for="review-note">Review note <span class="optional">Optional</span></label>
        <textarea id="review-note" name="note" rows="2" placeholder="What worked, or what would you change?"></textarea>
      </div>
    </form>

    <section class="summary" aria-labelledby="summary-heading">
      <h2 id="summary-heading">Your review</h2>
      <dl>
        <div><dt>Preferred option</dt><dd><output id="summary-pick" form="copy-review">No option selected</output></dd></div>
        <div><dt>Tone ratings</dt><dd><ul id="summary-ratings" aria-label="Tone ratings by option"></ul></dd></div>
        <div><dt>Note</dt><dd id="summary-note">No note added</dd></div>
      </dl>
    </section>
  </main>

  <template id="option-template">
    <article class="card">
      <header>
        <div class="option-title">
          <span class="letter" aria-hidden="true"></span>
          <h2></h2>
        </div>
        <label class="pick">
          <input name="preferred" type="radio">
          <span class="choose">Choose</span><span class="selected" aria-hidden="true">Selected</span>
        </label>
      </header>
      <div class="preview">
        <div class="search-bar"><span class="magnifier" aria-hidden="true"></span>quarterly roadmap</div>
        <div class="results-bar">0 results</div>
        <div class="empty">
          <span class="empty-icon" aria-hidden="true"><span class="magnifier"></span></span>
          <h3></h3>
          <p></p>
        </div>
      </div>
      <fieldset class="rating">
        <legend>Tone rating <span class="sr-only"></span></legend>
        <div class="scale"></div>
        <div class="scale-labels" aria-hidden="true"><span>Poor fit</span><span>Great fit</span></div>
      </fieldset>
    </article>
  </template>
  <template id="score-template">
    <label class="score">
      <input class="sr-only" type="radio">
      <span aria-hidden="true"></span>
    </label>
  </template>
  <script>
    const options = [
      {
        key: '"'a', letter: 'A', name: 'Direct',
        headline: 'No results found',
        body: 'Try a different search term.'
      },
      {
        key: 'b', letter: 'B', name: 'Guiding',
        headline: 'No matches for “quarterly roadmap”',
        body: 'Check your spelling or try a broader search like “roadmap”.'
      },
      {
        key: 'c', letter: 'C', name: 'Conversational',
        headline: 'We came up empty',
        body: 'Try a shorter search. You might find what you’re looking for.'
      }
    ];

    const form = document.getElementById('copy-review');
    const cards = document.getElementById('options');
    const optionTemplate = document.getElementById('option-template');
    const scoreTemplate = document.getElementById('score-template');
    const summaryPick = document.getElementById('summary-pick');
    const summaryRatings = document.getElementById('summary-ratings');
    const summaryNote = document.getElementById('summary-note');
    const note = document.getElementById('review-note');
    const ratingSummaries = new Map();

    for (const option of options) {
      const label = 'Option ' + option.letter + ' · ' + option.name;
      const card = optionTemplate.content.cloneNode(true);
      card.querySelector('.letter').textContent = option.letter;
      card.querySelector('h2').textContent = option.name;
      card.querySelector('h3').textContent = option.headline;
      card.querySelector('.empty p').textContent = option.body;
      card.querySelector('legend .sr-only').textContent = ' for ' + label;

      const pick = card.querySelector('.pick input');
      pick.id = 'pick-' + option.key;
      pick.value = option.key;
      pick.setAttribute('aria-label', 'Choose ' + label);

      const scale = card.querySelector('.scale');
      for (let value = 1; value <= 5; value++) {
        const score = scoreTemplate.content.cloneNode(true);
        const input = score.querySelector('input');
        input.name = 'rating-' + option.key;
        input.id = input.name + '-' + value;
        input.value = value;
        const description = value === 1 ? ', poor fit' : value === 5 ? ', great fit' : '';
        input.setAttribute('aria-label', value + ' out of 5' + description);
        score.querySelector('span').textContent = value;
        scale.append(score);
      }
      cards.append(card);

      const ratingSummary = document.createElement('li');
      summaryRatings.append(ratingSummary);
      ratingSummaries.set(option.key, ratingSummary);
    }

    function render() {
      const values = new FormData(form);
      const chosen = options.find(option => option.key === values.get('preferred'));
      summaryPick.value = chosen ? 'Option ' + chosen.letter + ' · ' + chosen.name : 'No option selected';

      for (const option of options) {
        const rating = values.get('rating-' + option.key);
        ratingSummaries.get(option.key).textContent =
          option.letter + ' · ' + (rating ? rating + '/5' : 'Unrated');
      }
      summaryNote.textContent = note.value.trim() || 'No note added';
    }

    form.addEventListener('input', render);
    form.addEventListener('change', render);
    form.addEventListener('submit', event => event.preventDefault());
    render();
  </script>
</body>
</html>
